  const signature = req.header("X-DV-Signature");
  const rawBody = req.body;

  if (!verifySignature(rawBody, signature, process.env.CALLBACK_SECRET_KEY)) {
    return res.status(401).send("Invalid signature");
  }

  const event = JSON.parse(rawBody.toString("utf8"));
  res.status(204).end();
});

